// A winding hiking-trail visualization of progress toward the 500-mile goal,
// with milestone flags and a little rucksack marker showing current position.
function TrailProgress({ miles }) {
  const W = 400, H = 90, padX = 16;
  const usableW = W - padX * 2;
  const point = (f) => {
    const x = padX + f * usableW;
    const y = H / 2 + Math.sin(f * Math.PI * 3.1) * (H / 2 - 16);
    return { x, y };
  };
  const steps = 60;
  const fullPath = [...Array(steps + 1)].map((_, i) => point(i / steps));
  const toPathD = (pts) => pts.map((p, i) => `${i === 0 ? "M" : "L"}${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(" ");
  const pct = Math.max(0, Math.min(1, miles / GOAL_MILES));
  const doneSteps = Math.round(steps * pct);
  const current = point(pct);

  return (
    <svg viewBox={`0 0 ${W} ${H}`} width="100%" height="90" preserveAspectRatio="none">
      <path d={toPathD(fullPath)} fill="none" stroke={CHARCOAL} strokeWidth="4" strokeDasharray="1 9" strokeLinecap="round" />
      <path d={toPathD(fullPath.slice(0, doneSteps + 1))} fill="none" stroke={LIME} strokeWidth="4" strokeLinecap="round" />
      {MILESTONES.map((m) => {
        const { x, y } = point(m / GOAL_MILES);
        const reached = miles >= m;
        return (
          <g key={m}>
            <circle cx={x} cy={y} r="6" fill={reached ? LIME : INK} stroke={reached ? INK : "#555"} strokeWidth="2" />
            <text x={x} y={y - 11} textAnchor="middle" fontSize="9" fontWeight="bold" fill={reached ? LIME : "#888"}>{m}</text>
          </g>
        );
      })}
      <g transform={`translate(${current.x},${current.y})`}>
        <circle r="10" fill={LIME} stroke={INK} strokeWidth="2" />
        <text x="0" y="4" textAnchor="middle" fontSize="11">🎒</text>
      </g>
    </svg>
  );
}

// Turns a "YYYY-MM-DD" log key into "Month Day, Year"
function formatDateKey(dateKey) {
  const [y, m, d] = dateKey.split("-").map((v) => parseInt(v, 10));
  return `${MONTH_NAMES[m - 1]} ${d}, ${y}`;
}

const eventFor = (m, d) => EVENTS.find(e => e.month === m && e.day === d);
const pad = (n) => String(n).padStart(2, "0");
const keyFor = (m, d) => `${YEAR}-${pad(m + 1)}-${pad(d)}`;

function daysInMonth(m) {
  return new Date(YEAR, m + 1, 0).getDate();
}
// Monday-first weekday index (0=Mon ... 6=Sun)
function leadingBlanks(m) {
  const jsDay = new Date(YEAR, m, 1).getDay(); // 0=Sun
  return (jsDay + 6) % 7;
}

// Rucking calculator — estimates steps and calories from miles + weight carried
const STEPS_PER_MILE = 2100; // rucking stride is a touch shorter than a bare walk
function estimateSteps(miles) {
  return Math.round(miles * STEPS_PER_MILE);
}
function estimateCalories(miles, weightKg) {
  const caloriesPerMile = 100 + weightKg * 2.2; // base walking burn + load penalty
  return Math.round(miles * caloriesPerMile);
}

// Milestone badges along the way to the 500-mile goal
const MILESTONES = [50, 100, 250, 500];
const MILESTONE_LABELS = {
  50: "50 Mile Club",
  100: "Century Club",
  250: "Quarter-Thousand Club",
  500: "Ruck to the 500 — Complete!",
};

// Personal bests: longest ruck, heaviest carry, genuine Monday-first current weekly streak
function mondayKey(dateStr) {
  const d = new Date(dateStr + "T00:00:00");
  const day = (d.getDay() + 6) % 7;
  d.setDate(d.getDate() - day);
  return d.toISOString().slice(0, 10);
}
function currentChallengeWeekKey() {
  const now = new Date();
  if (now.getFullYear() < YEAR) return null;
  const capped = now.getFullYear() > YEAR ? new Date(YEAR, 11, 31) : now;
  const day = (capped.getDay() + 6) % 7;
  capped.setHours(0, 0, 0, 0);
  capped.setDate(capped.getDate() - day);
  return capped.toISOString().slice(0, 10);
}
function addDays(dateKey, days) {
  const d = new Date(dateKey + "T00:00:00");
  d.setDate(d.getDate() + days);
  return d.toISOString().slice(0, 10);
}
const TEST_UNLOCK_MONTH = 0; // TEMPORARY: all January 2027 dates unlocked for testing only
function isFutureChallengeDate(m, d) {
  if (m === TEST_UNLOCK_MONTH) return false;
  const target = new Date(YEAR, m, d, 23, 59, 59, 999);
  return target > new Date();
}

